function add(p,q){ var n=Math.max(p.length,q.length); var r=new Array(n).fill(0);
  for(var i=0;i<n;i++) r[i]=(p[i]||0)+(q[i]||0); return r; }
function mul(p,q){ var r=new Array(p.length+q.length-1).fill(0);
  for(var i=0;i<p.length;i++) for(var j=0;j<q.length;j++) r[i+j]+=p[i]*q[j]; return r; }
function eval(p,x){ var s=0; for(var i=0;i<p.length;i++){ var t=1; for(var k=0;k<i;k++) t*=x; s+=p[i]*t; } return s; }
var EXPORTS={add:add, mul:mul, eval:eval};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PolynomialForgePure = EXPORTS; }
